//! The bank of demo projects, from a single lower third to a multi-format
//! live show (generated by tools/demos/build.py, embedded in the server).

use cg_core::Project;
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DemoInfo {
    pub id: String,
    pub name: String,
    /// 1 (first steps) to 5 (everything together).
    pub level: u8,
    pub tags: Vec<String>,
    pub description: String,
}

#[derive(Deserialize)]
struct DemoFile {
    demo: DemoInfo,
    project: Project,
}

const FILES: &[&str] = include!("../demos/index.rs");

fn all() -> impl Iterator<Item = DemoFile> {
    FILES
        .iter()
        .filter_map(|j| match serde_json::from_str::<DemoFile>(j) {
            Ok(d) => Some(d),
            Err(e) => {
                tracing::error!("bad demo project: {e}");
                None
            }
        })
}

pub fn list() -> Vec<DemoInfo> {
    all().map(|d| d.demo).collect()
}

/// A copy of a demo, ready to be saved as a new project.
pub fn project(id: &str) -> Option<Project> {
    all().find(|d| d.demo.id == id).map(|d| d.project)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_demo_loads_and_renders() {
        let demos: Vec<DemoFile> = FILES
            .iter()
            .map(|j| serde_json::from_str(j).expect("a demo parses"))
            .collect();
        assert_eq!(demos.len(), FILES.len());
        let mut renderer = cg_render::Renderer::new(std::env::temp_dir().join("pulse-demo-test"));
        for d in &demos {
            let p = &d.project;
            let zones: Vec<&str> = p.zones.iter().map(|z| z.id.as_str()).collect();
            assert!(!p.templates.is_empty(), "{}: no template", d.demo.id);
            for r in &p.rundown {
                assert!(
                    p.template(&r.template_id).is_some(),
                    "{}: item {} without template",
                    d.demo.id,
                    r.name
                );
                assert!(
                    zones.contains(&r.zone.as_str()),
                    "{}: item {} in an unknown zone",
                    d.demo.id,
                    r.name
                );
            }
            for t in &p.templates {
                assert!(
                    zones.contains(&t.zone.as_str()),
                    "{}: template {} in an unknown zone",
                    d.demo.id,
                    t.name
                );
                // The graphics sit in their zone (they are cut to it on air).
                let zone = p.zones.iter().find(|z| z.id == t.zone).unwrap();
                let area = zone.area(cg_core::MAIN_FORMAT, false);
                for l in t.layers.iter().filter(|l| l.parent.is_none()) {
                    let n = |prop: cg_core::Prop| {
                        l.props
                            .get(&prop)
                            .and_then(|v| v.as_number())
                            .unwrap_or(0.0)
                    };
                    let (x, y, w, h) = (
                        n(cg_core::Prop::X),
                        n(cg_core::Prop::Y),
                        n(cg_core::Prop::Width),
                        n(cg_core::Prop::Height),
                    );
                    let (ax, ay) = (area.x * p.width as f64, area.y * p.height as f64);
                    let (aw, ah) = (area.width * p.width as f64, area.height * p.height as f64);
                    assert!(
                        x >= ax - 2.0
                            && y >= ay - 2.0
                            && x + w <= ax + aw + 2.0
                            && y + h <= ay + ah + 2.0,
                        "{}: {} / {} out of its zone {}",
                        d.demo.id,
                        t.name,
                        l.name,
                        zone.name
                    );
                }
                let data: cg_core::Data = t
                    .fields
                    .iter()
                    .map(|f| (f.key.clone(), f.default.clone()))
                    .collect();
                let hold = t
                    .markers
                    .iter()
                    .find(|m| m.kind == cg_core::MarkerKind::Out)
                    .map(|m| m.frame)
                    .unwrap_or(0.0);
                for f in std::iter::once(cg_core::MAIN_FORMAT)
                    .chain(p.formats.iter().map(|f| f.id.as_str()))
                {
                    let frame = renderer.render_template(p, t, f, hold, &data);
                    let png = frame.to_png();
                    assert!(png.len() > 100, "{}: {} renders", d.demo.id, t.name);
                }
            }
        }
    }
}
